 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Idle required");if(File.Exists(Q+"popcorn-caption-fit.json"))throw new Exception("Already applied");var setup=EditorSceneManager.GetSceneManagerSetup();try{var scene=EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/ShoeTower.unity");File.Copy(scene.path,Q+"recovery/ShoeTower-before-caption-fit.unity",false);var state=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("ApplyContent16")).First(t=>t!=null).GetMethod("State",BindingFlags.Static|BindingFlags.NonPublic);string before=(string)state.Invoke(null,new object[]{scene});var role=Object.FindFirstObjectByType<Chapter45Director>().GetComponentsInChildren<Chapter45RoleAction>(true).Single(r=>r.role==Chapter45RoleAction.Role.PopcornThrower);var root=role.heldProp.Find("ContentCycle16 generated popcorn container");var panels=root.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="Paper printed panel").ToArray();if(panels.Length!=4)throw new Exception("Expected four panels");foreach(var panel in panels){panel.localPosition=new Vector3(0,.52f,-.217f);panel.localScale=new Vector3(.38f,.28f,1);panel.localRotation=Quaternion.Euler(-4.5f,0,0);}if(before!=(string)state.Invoke(null,new object[]{scene}))throw new Exception("Game contract changed");EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");scene=EditorSceneManager.OpenScene(scene.path);if(before!=(string)state.Invoke(null,new object[]{scene}))throw new Exception("Reopened contract changed");var report=new{saved=true,changed="Four newly added paper panel transforms only",reason="Independent P3 close-up review found detached over-wide cards",width=.38f,height=.28f,centerDepth=-.217f,tiltDegrees=-4.5f,localCartonHeight=1,gameplayComponentsUnchanged=true,newPaidCalls=0,utc=DateTime.UtcNow};File.WriteAllText(Q+"popcorn-caption-fit.json",Json(report));return report;}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}}
